css:
.block{--c:#3aa9dc}.block:nth-child(2){--c:#7b78bd}.block:nth-child(3){--c:#35bfae}
.block .head{border-left:4px solid var(--c);padding-left:12px}
.block h3{color:var(--c)} .block li::marker{color:var(--c)}
/* 見出しをパレットの出所にする */
h3{background:linear-gradient(90deg,#f5a04a,#ef7fa5,#9a86d8,#6fa8dc,#7fc9ae);-webkit-background-clip:text;background-clip:text;color:transparent}
.row:nth-child(1) .dot{background:#f5a04a}.row:nth-child(2) .dot{background:#ef7fa5}.row:nth-child(3) .dot{background:#9a86d8}
